import re, json

P = 'chinese-dynasty.html'
s = open(P, encoding='utf-8').read()

# (id, year, period, short, title, category, figure, desc, bk, more)
E = [
 ('c1',-316,'战国·秦','秦灭蜀','秦将司马错灭蜀，得巴蜀之饶','军事风云','司马错、秦惠文王、蜀王开明','秦惠文王采司马错之计，自石牛道伐蜀，十月而灭开明氏，置蜀郡。巴蜀之饶自此尽为秦有，成为日后东出争天下的粮仓与兵源。','秦灭巴蜀','张仪随后按咸阳规制筑成都城，又取巴地置巴郡。司马错与张仪曾在秦廷当面争论“伐蜀”与“伐韩”之优劣，司马错以“得其地足以广国，取其财足以富民”胜出。'),
 ('c2',-293,'战国·秦','伊阙之战','白起伊阙斩首二十四万','军事风云','白起、魏冉、韩魏联军','秦将白起于伊阙避实击虚，先击弱旅再合围主力，斩首韩魏联军二十四万，拔五城。韩魏精锐尽丧，白起自此为秦军主将。','伊阙之战','此役后韩魏被迫割地求和，秦国东进通道洞开。白起由左更迁为国尉，开启其“战无不胜”的将帅生涯。'),
 ('c3',-249,'战国·楚','楚灭鲁','楚考烈王灭鲁，八百年鲁国绝祀','政治变革','楚考烈王、鲁顷公','楚考烈王伐鲁，迁鲁顷公于莒，周公所封、存续八百年的鲁国就此绝祀。','楚灭鲁','鲁国为周公旦封国，保存周礼最完整，素有“周礼尽在鲁矣”之称。孔子、孟子皆出于鲁，其亡象征周代礼乐秩序的最后余响消散。'),
 ('c4',-244,'战国·赵','李牧破匈','李牧雁门大破匈奴十余万骑','军事风云','李牧、赵悼襄王','赵将李牧久守雁门，坚壁清野、厚养士卒数年，继而诱敌深入，单日大破匈奴十余万骑，灭襜褴、破东胡、降林胡。此后十余年匈奴不敢近赵边。','李牧','李牧前期被赵王责为怯战而罢将，边地屡失；复职后仍行旧法，终成大功。此战为中国古代步兵围歼骑兵的经典战例。'),
 ('c5',-229,'战国·秦','秦灭赵','王翦反间，赵王杀李牧，邯郸陷落','军事风云','王翦、李牧、赵王迁、郭开','秦王翦攻赵受阻于李牧，乃以重金买通赵臣郭开行反间，赵王迁冤杀李牧。数月后邯郸陷落，赵公子嘉北走代地，山东六国已亡其四。','秦灭赵','李牧死而赵国亡，后世常与“廉颇老矣”“赵括纸上谈兵”并举，叹赵之自毁长城。'),
 ('c6',-227,'战国·燕','荆轲刺秦','图穷匕见，荆轲刺秦王不中','政治变革','荆轲、太子丹、秦舞阳','燕太子丹遣荆轲携督亢地图与樊於期首级入秦，图穷而匕见，刺秦王不中，荆轲被杀。秦大怒，发兵攻燕，燕王喜走保辽东。','荆轲刺秦王','易水送别，高渐离击筑，荆轲和歌“风萧萧兮易水寒，壮士一去兮不复还”，成为千古悲壮意象。'),
 ('c7',-225,'战国·秦','秦灭魏','王贲引河水灌大梁，魏亡','军事风云','王贲、魏王假','秦将王贲引黄河、鸿沟之水灌大梁三月，城坏，魏王假出降，魏国亡。','秦灭魏','大梁即今开封，此后数次因黄河决口而城毁。魏亡后秦设砀郡，三晋尽入秦版图。'),
 ('c8',-196,'西汉','韩信之死','吕后萧何诱斩韩信于长乐宫','政治变革','刘邦、吕后、萧何、韩信','吕后与萧何诈称陈豨已破，诱淮阴侯韩信入贺，斩于长乐宫钟室，夷三族。韩信临刑叹“吾悔不用蒯通之计”。','韩信','“成也萧何，败也萧何”即由此而来。韩信为汉初三杰之一，定三秦、破赵齐、垓下合围，功高震主而终不免。'),
 ('c9',-158,'西汉','细柳营','汉文帝劳军细柳，赞周亚夫真将军','军事风云','周亚夫、汉文帝','匈奴大入边，文帝遣三将军屯兵备胡，亲往劳军。至细柳营，军吏披甲持兵，天子不得驰入，周亚夫持兵揖曰“介胄之士不拜”。文帝叹“此真将军矣”。','周亚夫','此事成为中国治军严整的典范，后世“细柳”遂为军营代称。'),
 ('c10',-127,'西汉','河南之战','卫青收复河套，筑朔方城','军事风云','卫青、汉武帝','卫青率军自云中西出，西至陇西，收复河南地（河套），筑朔方城，置朔方郡，长安北顾之忧遂解。','河南之战','此为汉匈战争由守转攻的关键一役，此后汉朝以朔方、五原为北击匈奴的前进基地。'),
 ('c11',-111,'西汉','设敦煌郡','汉武帝置敦煌郡，筑玉门阳关','对外开拓','汉武帝、张骞','汉武帝分酒泉置敦煌郡，并于敦煌西境筑玉门关、阳关，扼控丝绸之路南北两道咽喉。','敦煌郡','“敦，大也；煌，盛也”。此后敦煌成为中原与西域交往的门户，莫高窟、汉简、藏经洞皆由此而生。'),
 ('c12',-100,'西汉','苏武牧羊','苏武持节牧羊北海十九年','对外开拓','苏武、且鞮侯单于','中郎将苏武出使匈奴被扣，拒不投降，被徙北海牧羊，曰“羝乳乃得归”。十九年间持汉节不失，节旄尽落。','苏武','前81年苏武白发归汉，拜典属国。其“留胡节不辱”成为后世气节的最高象征，班固赞其“使于四方，不辱君命”。'),
 ('c13',-91,'西汉','巫蛊之祸','江充构陷太子，长安血战五日','政治变革','汉武帝、江充、太子刘据、卫子夫','江充借巫蛊之事构陷太子刘据，太子矫诏起兵诛江充，与丞相军战于长安五日，兵败自尽，卫皇后亦自杀，牵连死者数万。','巫蛊之祸','事后武帝建“思子宫”、作归来望思之台，并下轮台诏悔过。此祸使汉室元气大伤，也为昭宣中兴的调整埋下伏笔。'),
 ('c14',-89,'西汉','轮台罪己','汉武帝下轮台诏，深陈征伐之悔','政治变革','汉武帝、桑弘羊','武帝晚年驳桑弘羊轮台屯田之议，下诏“当今务在禁苛暴，止擅赋，力本农”，深陈既往征伐之悔，转向与民休息。','轮台诏','此诏被视为中国历史上第一份帝王罪己诏，政策转向使西汉避免了亡秦之祸。'),
 ('c15',-74,'西汉','昭宣中兴','霍光废昌邑王，迎立汉宣帝','政治变革','霍光、汉宣帝、昌邑王刘贺','大将军霍光于未央宫奏废即位二十七日的昌邑王刘贺，迎立流落民间的戾太子之孙刘询，是为汉宣帝。轻徭薄赋、整顿吏治，史称昭宣中兴。','昭宣中兴','汉宣帝起于闾阎，知民间疾苦，设常平仓、降盐价、平理刑狱，吏称其职、民安其业，西汉国力至此而极。'),
 ('c16',57,'东汉','委奴金印','光武帝赐倭奴国王金印','对外开拓','汉光武帝、倭奴国使','倭奴国遣使朝贡，光武帝赐以“汉委奴国王”金印。此为中日官方交往见于中国正史之始。','汉委奴国王印','1784年该印出土于日本福冈志贺岛，蛇钮金印，现藏福冈市博物馆，为日本国宝。'),
 ('c17',82,'东汉','班固汉书','班固撰成《汉书》，开断代史体例','文明盛世','班固、班昭','班固继承父班彪之业，历二十余年撰成《汉书》一百篇，记西汉二百三十年史事，为中国第一部纪传体断代史。','汉书','班固死于狱中时书未竟，其妹班昭与马续续成八表与天文志。《汉书》与《史记》《后汉书》《三国志》并称“前四史”。'),
 ('c18',100,'东汉','说文解字','许慎撰《说文解字》，首创部首','文明盛世','许慎、贾逵','许慎博采篆文古籀，撰成《说文解字》十四篇，收字九千三百余，首创五百四十部首，为世界首部系统字典。','说文解字','“文”指独体字，“字”指合体字。此书保存了小篆字形与古义，是解读甲骨文、金文的桥梁，清代“说文学”由此大兴。'),
 ('c19',190,'汉末三国','董卓迁都','董卓焚洛阳，挟献帝西迁长安','政治变革','董卓、汉献帝、吕布','董卓为避关东联军兵锋，焚洛阳宫庙官府，挟献帝西迁长安，驱民数百万口，二百里内室屋荡尽，无复鸡犬。','董卓','洛阳经此一炬，东汉二百年帝都化为焦土。关东群雄名为讨董，实则各怀割据之志，天下大乱自此始。'),
 ('c20',192,'汉末三国','诛董卓','王允连环计，吕布诛董卓','政治变革','王允、吕布、貂蝉（演义）','司徒王允策反董卓义子吕布，于未央宫掖门伏兵诛卓，暴尸于市。','吕布','貂蝉连环计出于《三国演义》，正史仅载吕布与董卓侍婢私通、心不自安。董卓死后其部将李傕、郭汜反攻长安，王允遇害。'),
 ('c21',196,'汉末三国','挟天子都许','曹操迎献帝都许，奉天子以令不臣','政治变革','曹操、汉献帝、荀彧','曹操迎献帝自洛阳迁都于许，行屯田、修耕植，以“奉天子以令不臣”号令四方，霸业之基由此奠定。','挟天子以令诸侯','毛玠最早提出“奉天子以令不臣，修耕植以畜军资”。许都二十五年间成为北方政治中心。'),
 ('c22',205,'汉末三国','伤寒杂病论','张仲景撰《伤寒杂病论》，立辨证论治','文明盛世','张仲景','南阳张仲景感于宗族十年亡者三分有二，勤求古训、博采众方，撰《伤寒杂病论》十六卷，确立六经辨证与理法方药体系，后世尊为医圣。','伤寒杂病论','此书后经王叔和整理为《伤寒论》与《金匮要略》两部，所载桂枝汤、麻黄汤、小柴胡汤至今为临床常用方。'),
 ('c23',214,'汉末三国','刘备取益州','刘备围成都，刘璋出降','军事风云','刘备、刘璋、诸葛亮、法正','刘备自葭萌挥师南下，与刘璋决裂，诸葛亮、张飞、赵云溯江分定郡县，进围成都。刘璋开城出降，刘备领益州牧，跨有荆益。','益州之战','此役后三分之势成形。刘备以“厚树恩德”得蜀人之心，但荆州与益州两线分兵，也为日后关羽失荆州埋下隐患。'),
 ('c24',215,'汉末三国','逍遥津战','张辽八百破孙权十万','军事风云','张辽、李典、乐进、孙权','孙权率十万众围合肥，张辽募八百勇士凌晨冲阵，直杀至孙权麾下，吴军披靡。孙权退走时于逍遥津被追袭，几不得脱。','合肥之战','此役后张辽威震江东，“张辽止啼”成为典故。孙权终生忌惮合肥，多次北伐皆无功。'),
 ('c25',280,'西晋','晋灭东吴','王濬楼船下益州，孙皓出降','军事风云','王濬、杜预、王浑、孙皓','晋发兵二十余万，六路伐吴。王濬楼船自益州顺流而下，直抵建业，孙皓面缚出降。三国分裂九十余年至此复归一统。','晋灭吴','刘禹锡《西塞山怀古》“王濬楼船下益州，金陵王气黯然收”即咏此役。'),
 ('c26',316,'西晋','西晋灭亡','刘曜陷长安，晋愍帝出降','政治变革','刘曜、晋愍帝','汉赵刘曜攻陷长安，城中户不盈百、公私车四乘，晋愍帝出降，西晋亡。中原板荡，衣冠南渡。','永嘉之乱','此前洛阳已陷（311），怀帝被掳，史称永嘉之乱。西晋统一仅三十七年，八王之乱自毁根基。'),
 ('c27',317,'东晋','东晋建立','司马睿建康称帝，王与马共天下','政治变革','司马睿、王导、王敦','司马睿于建康称晋王，次年称帝，建立东晋。琅琊王氏王导主政、王敦掌兵，时谚“王与马，共天下”。','东晋','东晋凭长江天险与门阀支持立国百余年，北伐屡起而屡止，淝水之战后得以续命。'),
 ('c28',366,'十六国','莫高窟开','乐僔开凿莫高窟第一窟','文明盛世','乐僔、敦煌僧俗','沙门乐僔行至敦煌鸣沙山东麓，忽见金光如现千佛，遂凿窟造像，是为莫高窟第一窟。此后千年营造不辍。','莫高窟','现存洞窟735个、壁画4.5万平方米、彩塑2400余尊，1987年列入世界文化遗产。'),
 ('c29',401,'十六国','罗什译经','鸠摩罗什入长安，译经三百余卷','文明盛世','鸠摩罗什、姚兴','后秦姚兴伐破后凉，迎鸠摩罗什入长安，待以国师之礼，于草堂寺主持译场。十余年间译出《金刚经》《法华经》《维摩诘经》等三百余卷。','鸠摩罗什','其译经“义皆圆通”，一改旧译之滞，“烦恼”“世界”“未来”“刹那”等词自此进入汉语。与真谛、玄奘、不空并称四大译经家。'),
 ('c30',460,'北魏','云冈石窟','昙曜于武州山开凿五窟','文明盛世','昙曜、北魏文成帝','文成帝命沙门昙曜于平城西武州山开凿五窟，各铸佛像一尊，象征北魏五帝，即“昙曜五窟”，云冈石窟自此而兴。','云冈石窟','第20窟露天大佛高13.7米，为云冈标志。石窟融合犍陀罗、秣菟罗与中原风格，是佛教艺术中国化的关键一环。'),
 ('c31',462,'南朝·宋','祖率问世','祖冲之推圆周率至七位小数','文明盛世','祖冲之','祖冲之推算出圆周率在3.1415926与3.1415927之间，并以22/7为约率、355/113为密率，领先世界近千年。又创《大明历》，引入岁差。','祖冲之','密率355/113直至16世纪才被欧洲重新发现。祖冲之还造指南车、千里船、水碓磨，为南朝最杰出的科学家。'),
 ('c32',485,'北魏','均田制','北魏颁均田制与三长制','政治变革','北魏孝文帝、冯太后、李冲','北魏依李冲之议，废宗主督护、立三长制，继而颁均田令，按丁授露田桑田，整顿户籍与赋役。','均田制','此为隋唐均田制与租庸调之先声，也是北朝能够重建编户齐民社会、最终统一南北的制度基础。'),
 ('c33',520,'北魏','水经注','郦道元撰《水经注》四十卷','文明盛世','郦道元','郦道元博考群书、参验实地，为《水经》作注，记水道一千二百余条，兼载地理沿革、山川风物、碑刻传说，成书四十卷。','水经注','文笔清丽，“三峡”“河水”诸篇为历代散文典范。与《洛阳伽蓝记》《齐民要术》并称北魏三大名著。'),
 ('c34',675,'唐朝','滕王阁序','王勃即席赋《滕王阁序》','文明盛世','王勃、阎伯屿','王勃省亲途经洪州，适逢都督阎伯屿重修滕王阁宴客，即席挥毫成《秋日登洪府滕王阁饯别序》，“落霞与孤鹜齐飞，秋水共长天一色”满座皆惊。','滕王阁序','王勃为“初唐四杰”之首，此文骈散结合，用典精切，为骈文巅峰。次年王勃渡海溺水，惊悸而卒，年仅二十七。'),
 ('c35',705,'唐朝','神龙政变','张柬之等诛二张，武则天禅位','政治变革','张柬之、李显、张易之、武则天','宰相张柬之等率羽林军入宫诛张易之、张昌宗，逼武则天禅位于太子李显，复唐国号，武周终结。','神龙政变','武则天退位同年病逝，遗诏去帝号、称“则天大圣皇后”，与高宗合葬乾陵，立无字碑。'),
 ('c36',710,'唐朝','唐隆政变','李隆基夜诛韦后，拥睿宗复位','政治变革','李隆基、太平公主、韦后、安乐公主','韦后与安乐公主毒杀中宗、临朝称制。临淄王李隆基联合太平公主夜率羽林军入宫，诛韦后、安乐公主及其党羽，拥父李旦复位。','唐隆政变','两年后李隆基再发动先天政变诛太平公主党羽，始得亲政，次年改元开元。'),
 ('c37',744,'唐朝','李杜相逢','李白与杜甫初遇洛阳，同游梁宋','文明盛世','李白、杜甫、高适','李白赐金放还后至洛阳，与杜甫初次相遇，二人同游梁宋，又与高适相会，猎于孟诸，饮酒论诗。','李杜','闻一多称此次相遇“是中国文学史上最重大的事件之一”。二人此后再未相见，杜甫却终身怀念，写下十余首忆李白之作。'),
 ('c38',748,'唐朝','鉴真东渡','鉴真六次东渡终抵日本','对外开拓','鉴真、荣睿、普照','扬州大明寺高僧鉴真应日本僧人荣睿、普照之请，六次东渡，历经海难、失明，终抵奈良，于东大寺设坛授戒，后建唐招提寺。','鉴真','鉴真将佛法、医药、建筑、雕塑、书法传入日本，被尊为“天平之甍”。其坐像为日本国宝。'),
 ('c39',765,'唐朝','单骑退敌','郭子仪单骑入回纥营退兵','军事风云','郭子仪、仆固怀恩、回纥','仆固怀恩引回纥、吐蕃数十万众逼京师。年近七旬的郭子仪免胄释甲，单骑入回纥营，回纥诸酋下马罗拜，遂倒戈共击吐蕃。','郭子仪','郭子仪“权倾天下而朝不忌，功盖一代而主不疑”，为唐代中兴第一名臣，寿八十五而终。'),
 ('c40',848,'唐朝','归义军','张议潮沙州起义，河西归唐','对外开拓','张议潮','张议潮于沙州起义，逐吐蕃守将，遣使奉表归唐。唐置归义军，以张议潮为节度使，河西千里故地渐次收复。','张议潮','敦煌莫高窟第156窟《张议潮统军出行图》即记其事。归义军延续近二百年，保存了汉家衣冠与敦煌文献。'),
 ('c41',965,'北宋','宋灭后蜀','宋师六十六日灭后蜀','军事风云','王全斌、孟昶、花蕊夫人','宋遣王全斌等分道伐蜀，前后六十六日后蜀亡，孟昶出降。花蕊夫人被俘入宋，赋“十四万人齐解甲，更无一个是男儿”。','宋灭后蜀','宋得蜀中财赋，国用始足。但王全斌纵兵掠蜀，激起全师雄兵变，蜀地数年方定。'),
 ('c42',1023,'北宋','交子发行','北宋设益州交子务，发行官交子','文明盛世','宋仁宗、薛田、张若谷','北宋于成都设益州交子务，由官府统一发行“交子”，以铁钱为准备金，分界流通。此为世界最早的官方纸币。','交子','交子初由成都十六户富商联合发行，后因挤兑争讼改为官办。元代纸币、西方近代银行券皆源此思路。'),
 ('c43',1153,'金朝','金迁中都','海陵王迁都燕京，定名中都','政治变革','海陵王完颜亮','金海陵王完颜亮自上京会宁府迁都燕京，定名中都大兴府，仿汴京规制营建宫城，北京作为王朝帝都的历史由此开启。','金中都','此前金上京偏处东北，难以控御中原。迁都后金朝完成向中原王朝的转型，也为元大都、明清北京奠定城址基础。'),
 ('c44',1175,'南宋','鹅湖之会','朱熹与陆九渊鹅湖论辩','文明盛世','朱熹、陆九龄、陆九渊、吕祖谦','吕祖谦邀朱熹与陆氏兄弟会讲于信州铅山鹅湖寺，就“格物致知”与“发明本心”往复论辩三日，各执己见而散。','鹅湖之会','此为理学与心学的首次正面交锋，是中国思想史上的标志性事件。十余年后朱陆再会于白鹿洞，气氛始缓和。'),
 ('c45',1215,'大蒙古国','蒙古破中都','成吉思汗攻占金中都','军事风云','成吉思汗、木华黎、金宣宗','蒙古大军围中都，金宣宗已南迁汴京。城中粮尽，守将自杀，蒙古入城，宫阙焚毁。华北尽入蒙古。','蒙古攻金','金朝自野狐岭（1211）后连战连败，中都陷落后仅余河南一隅，二十年后为蒙古所灭。'),
 ('c46',1247,'南宋','洗冤集录','宋慈撰《洗冤集录》','文明盛世','宋慈','提点刑狱宋慈总结数十年检验经验，撰成《洗冤集录》五卷，系统论述验尸、验骨、中毒鉴别与检验程序，为世界首部法医学专著。','洗冤集录','此书比欧洲第一部法医学著作早三百五十余年，先后译成朝、日、英、法、德、俄等文字。'),
 ('c47',1253,'大蒙古国','忽必烈灭大理','忽必烈革囊渡江，奇袭灭大理','军事风云','忽必烈、兀良合台、段兴智','忽必烈率军自临洮南下，以革囊渡金沙江，千里奇袭，攻灭大理国，俘段兴智。此后蒙古得以从西南迂回包抄南宋。','大理国','大理国立国三百余年，崇佛、重文，段氏世为国王。灭国后仍以段氏为世袭总管，元明相沿。'),
 ('c48',1276,'元朝','临安降元','伯颜兵临临安，谢太后奉玺出降','政治变革','伯颜、谢太后、宋恭帝','元军伯颜分三路合围临安，谢太后携五岁宋恭帝奉传国玺出降，南宋朝廷覆亡。文天祥、张世杰、陆秀夫等拥二王继续抗元。','临安之战','宋室三百年基业至此终结，但崖山之前，抗元力量仍在闽广坚持三年。'),
 ('c49',1283,'元朝','文天祥就义','文天祥柴市口从容就义','政治变革','文天祥、忽必烈','文天祥囚于大都土室四年，作《正气歌》明志。忽必烈亲劝降许以宰相，答曰“愿赐一死足矣”。于柴市口南向再拜，从容就义，年四十七。','文天祥','衣带中留有绝笔：“孔曰成仁，孟曰取义，惟其义尽，所以仁至。读圣贤书，所学何事？而今而后，庶几无愧。”'),
 ('c50',1291,'元朝','窦娥冤','关汉卿作《感天动地窦娥冤》','文明盛世','关汉卿','关汉卿于大都创作杂剧《感天动地窦娥冤》，写民女窦娥蒙冤被斩，临刑发三桩誓愿——血溅白练、六月飞雪、大旱三年，一一应验。','窦娥冤','关汉卿为“元曲四大家”之首，一生作杂剧六十余种。此剧被誉为“中国悲剧之最”，1842年即有法译本。'),
 ('c51',1457,'明朝','夺门之变','石亨等迎英宗复辟，于谦冤死','政治变革','石亨、徐有贞、明英宗、于谦','景泰帝病重，石亨、徐有贞等率兵破南宫，迎太上皇朱祁镇复辟，改元天顺。兵部尚书于谦以“意欲”之罪被杀，天下冤之。','夺门之变','于谦曾于土木之变后拥立景泰帝、组织北京保卫战，挽救明室。抄家时“家无余资，萧然仅书籍耳”。'),
 ('c52',1553,'明朝','葡租澳门','葡萄牙人获准居留澳门','对外开拓','葡萄牙人、汪柏','葡萄牙商船以曝晒水渍贡物为由，贿通广东海道副使汪柏，获准在澳门搭棚暂居，岁输地租。此后澳门渐成中西贸易枢纽。','澳门','1557年起葡人正式居留，1887年《中葡和好通商条约》使其取得“永居管理”之权。1999年12月20日澳门回归中国。'),
 ('c53',1578,'明朝','本草纲目','李时珍撰成《本草纲目》','文明盛世','李时珍','李时珍历二十七年、三易其稿，参考八百余种典籍，成《本草纲目》五十二卷，收药一千八百九十二种，附方一万一千余首。','本草纲目','此书首创按自然属性分类的纲目体例，被达尔文称为“中国古代百科全书”。2011年入选世界记忆名录。'),
 ('c54',1583,'明朝','利玛窦入华','利玛窦入肇庆，绘《山海舆地全图》','对外开拓','利玛窦、罗明坚','耶稣会士利玛窦获准进入两广总督驻地肇庆，建仙花寺，绘中文世界地图《山海舆地全图》，以“西儒”身份传播西学。','利玛窦','利玛窦与徐光启合译《几何原本》，与李之藻合绘《坤舆万国全图》。西学东渐与“礼仪之争”皆自其始。'),
 ('c55',1598,'明朝','牡丹亭','汤显祖成《牡丹亭》','文明盛世','汤显祖','汤显祖于抚州临川玉茗堂写成《牡丹亭还魂记》，写杜丽娘因梦而死、因情复生，“情不知所起，一往而深”，为“临川四梦”之冠。','牡丹亭','汤显祖与莎士比亚同年卒（1616）。《牡丹亭》上承《西厢记》，下启《红楼梦》，是中国戏曲浪漫主义的巅峰。'),
 ('c56',1613,'明朝','霞客开游','徐霞客游天台山，游记开篇','文明盛世','徐霞客','徐霞客自宁海出西门游天台山，写下游记开篇。此后三十四年间，他东渡普陀、西至腾冲、北历燕冀、南涉闽粤，遍历十四省。','徐霞客','《徐霞客游记》开篇之日（5月19日）现为“中国旅游日”。其石灰岩地貌考察早于欧洲约两百年。'),
 ('c57',1629,'明朝','己巳之变','皇太极破喜峰口，兵逼北京','军事风云','皇太极、袁崇焕、崇祯帝','皇太极绕道蒙古，破喜峰口入塞，连下遵化、三河，直逼北京。袁崇焕率关宁铁骑千里驰援，于广渠门外血战却敌。','己巳之变','此役后金首次入塞，暴露了关宁锦防线的侧翼空虚。崇祯帝中反间计，次年磔袁崇焕。'),
 ('c58',1630,'明朝','崇焕蒙冤','崇祯磔袁崇焕于西市，自毁长城','政治变革','崇祯帝、袁崇焕、皇太极','皇太极施反间计，使宦官密告袁崇焕通敌。崇祯帝将其下狱，次年八月磔于北京西市，兄弟妻子流三千里。','袁崇焕','袁崇焕曾以“五年复辽”自许，宁远大捷以红夷大炮重伤努尔哈赤。其死使辽东再无可倚之帅。'),
 ('c59',1637,'明朝','天工开物','宋应星刊行《天工开物》','文明盛世','宋应星','宋应星任分宜教谕期间，整理多年实地考察，刊行《天工开物》三卷十八篇，系统记载农业与冶金、纺织、造纸、制盐、陶瓷等百工技艺。','天工开物','全书附插图一百二十余幅，被誉为“中国十七世纪的工艺百科全书”，对研究明代科技与生产极具价值。'),
 ('c60',1669,'清朝','康熙擒鳌拜','康熙智擒辅臣鳌拜，始得亲政','政治变革','康熙帝、鳌拜、索额图','十六岁的康熙帝选侍卫少年习布库之戏，待鳌拜入见时突令擒之，列其三十大罪，免死禁锢。康熙自此亲政。','鳌拜','鳌拜为顺治遗诏四辅臣之一，专权跋扈、圈地害民。擒鳌拜是康熙亲政的第一步，也显示了其少年老成的政治手腕。'),
 ('c61',1696,'清朝','昭莫多战','康熙亲征朔漠，大破噶尔丹','军事风云','康熙帝、费扬古、噶尔丹','康熙帝第三次亲征噶尔丹，西路费扬古于昭莫多设伏，以火器与骑兵夹击，大破准噶尔主力。噶尔丹仅以身免，次年败死。','昭莫多之战','此战与乌兰布通之战（1690）共同奠定清朝对漠北蒙古的控制，为日后设乌里雅苏台将军、统一新疆铺路。'),
 ('c62',1718,'清朝','皇舆全览','康熙组织实测，绘成《皇舆全览图》','文明盛世','康熙帝、白晋、雷孝思','康熙帝命传教士白晋、雷孝思等分赴各省，以三角测量法实测经纬，历十年绘成《皇舆全览图》，为中国首部实测全国地图。','皇舆全览图','全图采用梯形投影，标注经纬网，其精度远超此前任何中国地图。李约瑟称其为“世界地图学史上的重要里程碑”。'),
 ('c63',1726,'清朝','改土归流','雍正于西南推行改土归流','政治变革','雍正帝、鄂尔泰','雍正帝用云贵总督鄂尔泰之策，于西南大规模废除世袭土司、改设流官，设府厅州县，编查户口、清丈田亩。','改土归流','此策涉及滇黔桂川湘诸省，强化了中央对边疆的直接治理，但也因用兵与剥夺土司特权引发多次反抗。'),
 ('c64',1763,'清朝','红楼梦','曹雪芹逝，遗《红楼梦》八十回','文明盛世','曹雪芹、高鹗','曹雪芹于北京西山贫病交加中去世，遗《石头记》（《红楼梦》）前八十回抄本。后四十回一般认为是高鹗、程伟元整理续补。','红楼梦','全书以贾府盛衰为线，写尽人情世态，为章回小说巅峰。“红学”自清至今蔚为大观。'),
 ('c65',1793,'清朝','马戛尔尼来','英使马戛尔尼觐见乾隆，通商遭拒','对外开拓','乾隆帝、马戛尔尼','英国使团以贺乾隆八十大寿为名来华，于热河避暑山庄觐见，提出开放口岸、设商馆、减税等请求，尽遭拒绝。','马戛尔尼使团','使团沿途测绘舆图、记录军备，得出“中华帝国只是一艘破旧不堪的头等战舰”的判断。半个世纪后鸦片战争爆发。'),
 ('c66',1854,'清朝','湘军创立','曾国藩于衡州创办湘军','军事风云','曾国藩、罗泽南、彭玉麟','曾国藩以在籍侍郎身份于湖南衡州办团练，仿戚继光束伍之法，建湘军水陆师，颁《讨粤匪檄》，以“卫道”为号召。','湘军','湘军“兵为将有”的体制改变了清代兵制，也开启了晚清督抚专兵、汉族官僚崛起的格局。'),
 ('c67',1872,'清朝','轮船招商局','李鸿章创办轮船招商局','政治变革','李鸿章、盛宣怀、唐廷枢','李鸿章于上海创办轮船招商局，官督商办，购船营运沿海与长江航线，打破外资轮船公司垄断。为中国近代第一家民族航运企业。','轮船招商局','招商局后创办开平矿务局、中国通商银行等，是洋务运动“官督商办”模式的样板，其血脉延续至今。'),
 ('c68',1878,'清朝','收复新疆','左宗棠克复喀什噶尔，新疆底定','军事风云','左宗棠、刘锦棠、阿古柏','左宗棠督师西征，采取“先北后南、缓进急战”之策，连克乌鲁木齐、达坂城、喀什噶尔，阿古柏败死。除伊犁外，天山南北尽复。','左宗棠收复新疆','左宗棠舆榇出关以示死战决心，沿途植柳，“左公柳”至今犹存。1884年新疆正式建省。'),
 ('c69',1884,'清朝','马江海战','法舰突袭马尾，福建水师覆没','军事风云','孤拔、张佩纶、何如璋','中法战争期间，法国舰队以“游历”为名驶入马尾港，突袭福建水师。半小时内清军舰船尽没，船政局被炮毁，伤亡七百余人。','马江海战','此役暴露清廷海防之弊。次年镇南关大捷、刘铭传守台，清廷仍以《中法新约》承认法国对越南的保护权。'),
 ('c70',1901,'清朝','辛丑条约','清廷与十一国签订《辛丑条约》','政治变革','李鸿章、奕劻、列强十一国','清廷与十一国签订《辛丑条约》：赔款四亿五千万两、分三十九年偿还，划东交民巷为使馆界驻兵，拆大沽炮台，禁止中国人民反帝。','辛丑条约','本息合计约九亿八千万两，以关税、盐税抵押。此约标志着中国完全沦为半殖民地半封建社会。'),
]

def js(s):
    return s.replace("\\", "\\\\").replace("'", "\\'")

lines = []
lines.append('\n    /* 与「江山时序」核对后补齐的重大事件（70 条） */')
lines.append('    const COMPAT_EVENTS = [')
for (i, y, per, short, title, cat, fig, desc, bk, more) in E:
    assert len(short) <= 6, (short, len(short))
    lines.append(
        "      { id: '%s', year: %d, period: '%s', shortTitle: '%s', title: '%s', category: '%s', figure: '%s',\n"
        "        desc: '%s' }," % (i, y, js(per), js(short), js(title), js(cat), js(fig), js(desc))
    )
lines.append('    ];')
block = '\n'.join(lines)

meta = ['\n    /* 补齐事件的百科与扩展（与 COMPAT_EVENTS 一一对应） */', '    Object.assign(EVENT_META, {']
for (i, y, per, short, title, cat, fig, desc, bk, more) in E:
    meta.append("      %s: { bk: '%s', more: '%s' }," % (i, js(bk), js(more)))
meta.append('    });')
mblock = '\n'.join(meta)

# 插入到 HISTORICAL_EVENTS.push(...EXTRA_EVENTS, ...WAR_EVENTS); 之前
anchor = '    HISTORICAL_EVENTS.push(...EXTRA_EVENTS, ...WAR_EVENTS);'
assert s.count(anchor) == 1
s = s.replace(anchor, block + '\n\n' + mblock + '\n\n' + '    HISTORICAL_EVENTS.push(...EXTRA_EVENTS, ...WAR_EVENTS, ...COMPAT_EVENTS);')

open(P, 'w', encoding='utf-8').write(s)
print('events added', len(E))
